using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Uses constructor injection — the SDK creates a new instance per invocation,
/// resolving HttpClient and ILogger from the DI container automatically.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all items from the API. Returns JSON array.")]
    public async Task<string> ListItems(CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing all items");
        var json = await httpClient.GetStringAsync("/items", cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get a single item by its unique identifier.")]
    public async Task<string> GetItem(
        [Description("The unique identifier of the item to retrieve")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Getting item {Id}", id);
        var response = await httpClient.GetAsync($"/items/{Uri.EscapeDataString(id)}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: {response.StatusCode}";
        }

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new item with a name and optional description.")]
    public async Task<string> CreateItem(
        [Description("Name for the new item")] string name,
        [Description("Optional description of the item")] string? description = null,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating item {Name}", name);

        var payload = JsonSerializer.Serialize(new { name, description }, JsonOptions);
        var content = new StringContent(payload, Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync("/items", content, cancellationToken);
        var body = await response.Content.ReadAsStringAsync(cancellationToken);

        return response.IsSuccessStatusCode
            ? body
            : $"Error ({response.StatusCode}): {body}";
    }

    [McpServerTool(Destructive = true),
     Description("Delete an item by its unique identifier. This action cannot be undone.")]
    public async Task<string> DeleteItem(
        [Description("The unique identifier of the item to delete")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Deleting item {Id}", id);
        var response = await httpClient.DeleteAsync($"/items/{Uri.EscapeDataString(id)}", cancellationToken);

        return response.IsSuccessStatusCode
            ? $"Deleted item {id}"
            : $"Error: {response.StatusCode}";
    }
}

